SET NAMES utf8mb4;

-- =====================================================================
-- AI LAB HUB — партія 2026-11-18: «Українські додатки» / «Ukrainian Apps» (slug ukrainian-apps): для дітей (казки, абетка, читання), українська мова (словники, правопис, суржик), аграріям і пасічникам.
-- Нові підкатегорії:
--   * Для дітей: казки й абетка / For Kids: Tales & Alphabet (slug ua-kids)
--   * Українська мова / Ukrainian Language (slug ua-language)
--   * Аграріям і пасічникам / Farmers & Beekeepers (slug ua-agro)
-- + 20 продуктів (якщо продукт із такою адресою чи назвою вже є — лише прив'язка, тексти не змінюються).
-- Тексти UA/EN написано за офіційними описами застосунків в App Store (регіон UA) та сайтами, звірено 2026-11-18.
-- Ціни не вказано: план «Ціна: див. сайт» (0, one_time); Free — застосунок безкоштовний у магазині застосунків.
-- Пропущено: Аудіоказки Українською (застосунок з 2023), Балакаюча АБЕТКА (з 2016), Ранок (з 2021), Palianytsia (з 2022), Український тлумачний словник (з 2020),
--   СкаЖений Агроном (з 2018); Lexykon, «Українська для держслужби», BeeKeeper, soft.farm (є російська версія), АгроМон (російськомовний опис);
--   іноземні компанії: Syngenta, Bayer, War Child («Вивчаю — не чекаю»), ALPA Kids, Наголос! (Канада); Marytale (без української мови).
-- Без фіксованих id: @new рахується ДО INSERT, @pid — за нормалізованою адресою або назвою.
-- Застосування: phpMyAdmin → БД → «Импорт». Повторний запуск безпечний.
--   Казки дитинства — Для дітей: казки й абетка
--   Skrynia: Bilingual stories — Для дітей: казки й абетка
--   ДобраКазка — казки на ніч українською — Для дітей: казки й абетка
--   Kazka — казки на ніч — Для дітей: казки й абетка
--   Abetka UA — Для дітей: казки й абетка
--   Абетка Українською — Для дітей: казки й абетка
--   Ukrainian alphabet: Kids ABC — Для дітей: казки й абетка
--   Bukvyk — Для дітей: казки й абетка
--   АБВ Читайка — Для дітей: казки й абетка
--   Мова — ДНК нації — Українська мова
--   UA Dictionary (СУМ-20) — Українська мова
--   СУМ — словник української мови — Українська мова
--   soloviy — словник живої української — Українська мова
--   No surzhyk — без суржику — Українська мова
--   alfa smart agro — Аграріям і пасічникам
--   Agrosfera — Аграріям і пасічникам
--   Feodal Land — Аграріям і пасічникам
--   MyField — Аграріям і пасічникам
--   Pasika — Аграріям і пасічникам
--   БджолоМаркет — Аграріям і пасічникам
-- =====================================================================

SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);
SET @cat = (SELECT `id` FROM `categories` WHERE `slug` = 'ukrainian-apps' LIMIT 1);
INSERT INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT @cat, 'Для дітей: казки й абетка', 'For Kids: Tales & Alphabet', 'ua-kids' FROM DUAL WHERE @cat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `subcategories` WHERE `category_id` = @cat AND `slug` = 'ua-kids');
INSERT INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT @cat, 'Українська мова', 'Ukrainian Language', 'ua-language' FROM DUAL WHERE @cat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `subcategories` WHERE `category_id` = @cat AND `slug` = 'ua-language');
INSERT INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT @cat, 'Аграріям і пасічникам', 'Farmers & Beekeepers', 'ua-agro' FROM DUAL WHERE @cat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `subcategories` WHERE `category_id` = @cat AND `slug` = 'ua-agro');

-- Казки дитинства — Для дітей: казки й абетка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kazky.net' OR LOWER(`name`) = 'казки дитинства')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Казки дитинства', NULL, 'https://kazky.net', NULL, NULL, 'Народні й авторські казки українською в тексті та аудіо, з офлайн-прослуховуванням.', 'Folk and author fairy tales in Ukrainian as text and audio, with offline listening.', 'Казки дитинства — збірка народних та авторських казок виключно українською мовою. Аудіоказки можна слухати онлайн у вбудованому плеєрі або завантажити й вмикати без інтернету. До кожної аудіоказки є текст, щоб дитина могла прочитати її самостійно. База казок постійно поповнюється й модерується.', 'Kazky Dytynstva is a collection of folk and author fairy tales exclusively in Ukrainian. Audio tales can be played online in the built-in player or downloaded for offline listening. Every audio tale comes with text so a child can read it on their own. The library is regularly expanded and moderated.', 'Казки в тексті й аудіо
Офлайн-прослуховування
Пошук і зручна навігація
Лише українською', 'Tales as text and audio
Offline listening
Search and easy navigation
Ukrainian only', 'Батькам дітей 3–8 років, зокрема українським родинам за кордоном.', 'Parents of children aged 3–8, including Ukrainian families abroad.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-11-18 00:00:00' FROM DUAL WHERE @new = 1;
