INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Skrynia: Bilingual stories', NULL, 'https://apps.apple.com/ua/app/id6470271125', NULL, NULL, 'Інтерактивні українські народні казки українською й англійською з розмальовками та словничком.', 'Interactive Ukrainian folk tales narrated in Ukrainian and English, with coloring and a vocabulary.', 'Skrynia — інтерактивні книжки для дітей від 3 років. Українські народні казки озвучено українською та англійською, ілюстрації можна розмальовувати просто в застосунку, а двомовний словничок допомагає вивчати нові слова. На кожній сторінці є прихований предмет, який треба знайти, — це тренує уважність.', 'Skrynia offers interactive storybooks for kids aged 3+. Ukrainian folk tales are narrated in Ukrainian and English, illustrations can be colored right in the app, and a bilingual vocabulary helps learn new words. Each page hides an object to find, which trains attention.', 'Казки українською та англійською
