-- Bukvyk — Для дітей: казки й абетка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bukvyk.com' OR LOWER(`name`) = 'bukvyk')), 1, 0);
