INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'No surzhyk — без суржику', NULL, 'https://apps.apple.com/ua/app/id6809286449', NULL, NULL, 'Слово дня, пошук українських відповідників калькам і запозиченням, живі голоси й перевірка тексту.', 'Word of the day, Ukrainian equivalents for calques and loanwords, real voices and a text checker.', 'No surzhyk допомагає спокійно, без повчань замінити звичні кальки й запозичення власне українськими словами. Щоранку — одна заміна з поясненням, звідки взялося чуже слово, і прикладами, як сказати й як не варто. Пошук знаходить відповідник за калькою чи категорією, кожне слово озвучують реальні люди, а вбудована перевірка тексту підказує, що замінити.', 'No surzhyk helps you calmly, without lecturing, replace familiar calques and loanwords with native Ukrainian words. Every morning brings one replacement with an explanation of where the foreign word came from and examples of what to say and what to avoid. Search finds an equivalent by calque or category, each word is voiced by real people, and a built-in text checker suggests what to replace.', 'Слово дня з поясненням
Пошук відповідників
Озвучення живими голосами
Перевірка тексту', 'Word of the day with explanation
